-- CreateTables：建表：注释、索引、外键一起建（外键排在全部建表之后）
CREATE TABLE IF NOT EXISTS "t_note" ("id" NUMBER(19) GENERATED BY DEFAULT AS IDENTITY NOT NULL, "title" VARCHAR2(255) NULL, "author_id" NUMBER(19) NOT NULL, "created_at" TIMESTAMP NOT NULL, PRIMARY KEY ("id"));
COMMENT ON TABLE "t_note" IS '笔记';
COMMENT ON COLUMN "t_note"."title" IS '标题';
CREATE INDEX "t_note_author_id_created_at_idx" ON "t_note" ("author_id" ASC, "created_at" DESC);
ALTER TABLE "t_note" ADD CONSTRAINT "t_note_t_user_id_fk" FOREIGN KEY ("author_id") REFERENCES "t_user" ("id") ON DELETE CASCADE;
SELECT t.table_name AS "table_name", c.comments AS "comment" FROM user_tables t LEFT JOIN user_tab_comments c ON c.table_name = t.table_name ORDER BY t.table_name;
SELECT c.table_name AS "table_name", c.column_name AS "column_name", LOWER(c.data_type) || CASE WHEN c.data_type IN ('VARCHAR2', 'NVARCHAR2', 'CHAR', 'NCHAR') THEN '(' || c.char_length || CASE c.char_used WHEN 'C' THEN ' char' ELSE '' END || ')' WHEN c.data_type = 'NUMBER' AND c.data_precision IS NOT NULL THEN '(' || c.data_precision || CASE WHEN c.data_scale > 0 THEN ', ' || c.data_scale ELSE '' END || ')' ELSE '' END AS "column_type", CASE c.nullable WHEN 'Y' THEN 1 ELSE 0 END AS "is_nullable", c.data_default AS "column_default", m.comments AS "comment", CASE c.identity_column WHEN 'YES' THEN 1 ELSE 0 END AS "is_generated", CASE WHEN EXISTS (SELECT 1 FROM user_constraints k JOIN user_cons_columns kc ON kc.constraint_name = k.constraint_name WHERE k.constraint_type = 'P' AND k.table_name = c.table_name AND kc.column_name = c.column_name) THEN 1 ELSE 0 END AS "primary_key" FROM user_tab_columns c LEFT JOIN user_col_comments m ON m.table_name = c.table_name AND m.column_name = c.column_name ORDER BY c.table_name, c.column_id;
SELECT i.table_name AS "table_name", i.index_name AS "index_name", CASE i.uniqueness WHEN 'UNIQUE' THEN 1 ELSE 0 END AS "is_unique", ic.column_name AS "column_name" FROM user_indexes i JOIN user_ind_columns ic ON ic.index_name = i.index_name WHERE NOT EXISTS (SELECT 1 FROM user_constraints k WHERE k.index_name = i.index_name AND k.constraint_type = 'P') ORDER BY i.table_name, i.index_name, ic.column_position;
SELECT k.table_name AS "table_name", k.constraint_name AS "constraint_name", kc.column_name AS "column_name", r.table_name AS "referenced_table", rc.column_name AS "referenced_column" FROM user_constraints k JOIN user_cons_columns kc ON kc.constraint_name = k.constraint_name JOIN user_constraints r ON r.constraint_name = k.r_constraint_name JOIN user_cons_columns rc ON rc.constraint_name = r.constraint_name AND rc.position = kc.position WHERE k.constraint_type = 'R' ORDER BY k.table_name, k.constraint_name, kc.position;

-- SyncTables：同步：先看要执行的语句，再执行；只增不删——改表名、改列名、加列、补索引
SELECT t.table_name AS "table_name", c.comments AS "comment" FROM user_tables t LEFT JOIN user_tab_comments c ON c.table_name = t.table_name ORDER BY t.table_name;
SELECT c.table_name AS "table_name", c.column_name AS "column_name", LOWER(c.data_type) || CASE WHEN c.data_type IN ('VARCHAR2', 'NVARCHAR2', 'CHAR', 'NCHAR') THEN '(' || c.char_length || CASE c.char_used WHEN 'C' THEN ' char' ELSE '' END || ')' WHEN c.data_type = 'NUMBER' AND c.data_precision IS NOT NULL THEN '(' || c.data_precision || CASE WHEN c.data_scale > 0 THEN ', ' || c.data_scale ELSE '' END || ')' ELSE '' END AS "column_type", CASE c.nullable WHEN 'Y' THEN 1 ELSE 0 END AS "is_nullable", c.data_default AS "column_default", m.comments AS "comment", CASE c.identity_column WHEN 'YES' THEN 1 ELSE 0 END AS "is_generated", CASE WHEN EXISTS (SELECT 1 FROM user_constraints k JOIN user_cons_columns kc ON kc.constraint_name = k.constraint_name WHERE k.constraint_type = 'P' AND k.table_name = c.table_name AND kc.column_name = c.column_name) THEN 1 ELSE 0 END AS "primary_key" FROM user_tab_columns c LEFT JOIN user_col_comments m ON m.table_name = c.table_name AND m.column_name = c.column_name ORDER BY c.table_name, c.column_id;
SELECT i.table_name AS "table_name", i.index_name AS "index_name", CASE i.uniqueness WHEN 'UNIQUE' THEN 1 ELSE 0 END AS "is_unique", ic.column_name AS "column_name" FROM user_indexes i JOIN user_ind_columns ic ON ic.index_name = i.index_name WHERE NOT EXISTS (SELECT 1 FROM user_constraints k WHERE k.index_name = i.index_name AND k.constraint_type = 'P') ORDER BY i.table_name, i.index_name, ic.column_position;
SELECT k.table_name AS "table_name", k.constraint_name AS "constraint_name", kc.column_name AS "column_name", r.table_name AS "referenced_table", rc.column_name AS "referenced_column" FROM user_constraints k JOIN user_cons_columns kc ON kc.constraint_name = k.constraint_name JOIN user_constraints r ON r.constraint_name = k.r_constraint_name JOIN user_cons_columns rc ON rc.constraint_name = r.constraint_name AND rc.position = kc.position WHERE k.constraint_type = 'R' ORDER BY k.table_name, k.constraint_name, kc.position;
ALTER TABLE "t_tag" RENAME TO "t_label";
ALTER TABLE "t_label" RENAME COLUMN "name" TO "title";
ALTER TABLE "t_label" ADD ("color" VARCHAR2(255) NULL);
COMMENT ON COLUMN "t_label"."color" IS '颜色';
CREATE UNIQUE INDEX "t_label_title_uidx" ON "t_label" ("title" ASC);

-- ReadTables：读库结构：列、主键、索引、外键
SELECT t.table_name AS "table_name", c.comments AS "comment" FROM user_tables t LEFT JOIN user_tab_comments c ON c.table_name = t.table_name ORDER BY t.table_name;
SELECT c.table_name AS "table_name", c.column_name AS "column_name", LOWER(c.data_type) || CASE WHEN c.data_type IN ('VARCHAR2', 'NVARCHAR2', 'CHAR', 'NCHAR') THEN '(' || c.char_length || CASE c.char_used WHEN 'C' THEN ' char' ELSE '' END || ')' WHEN c.data_type = 'NUMBER' AND c.data_precision IS NOT NULL THEN '(' || c.data_precision || CASE WHEN c.data_scale > 0 THEN ', ' || c.data_scale ELSE '' END || ')' ELSE '' END AS "column_type", CASE c.nullable WHEN 'Y' THEN 1 ELSE 0 END AS "is_nullable", c.data_default AS "column_default", m.comments AS "comment", CASE c.identity_column WHEN 'YES' THEN 1 ELSE 0 END AS "is_generated", CASE WHEN EXISTS (SELECT 1 FROM user_constraints k JOIN user_cons_columns kc ON kc.constraint_name = k.constraint_name WHERE k.constraint_type = 'P' AND k.table_name = c.table_name AND kc.column_name = c.column_name) THEN 1 ELSE 0 END AS "primary_key" FROM user_tab_columns c LEFT JOIN user_col_comments m ON m.table_name = c.table_name AND m.column_name = c.column_name ORDER BY c.table_name, c.column_id;
SELECT i.table_name AS "table_name", i.index_name AS "index_name", CASE i.uniqueness WHEN 'UNIQUE' THEN 1 ELSE 0 END AS "is_unique", ic.column_name AS "column_name" FROM user_indexes i JOIN user_ind_columns ic ON ic.index_name = i.index_name WHERE NOT EXISTS (SELECT 1 FROM user_constraints k WHERE k.index_name = i.index_name AND k.constraint_type = 'P') ORDER BY i.table_name, i.index_name, ic.column_position;
SELECT k.table_name AS "table_name", k.constraint_name AS "constraint_name", kc.column_name AS "column_name", r.table_name AS "referenced_table", rc.column_name AS "referenced_column" FROM user_constraints k JOIN user_cons_columns kc ON kc.constraint_name = k.constraint_name JOIN user_constraints r ON r.constraint_name = k.r_constraint_name JOIN user_cons_columns rc ON rc.constraint_name = r.constraint_name AND rc.position = kc.position WHERE k.constraint_type = 'R' ORDER BY k.table_name, k.constraint_name, kc.position;

